ALTER TABLE "ManagedMarketingPackageVersion" ADD COLUMN "name" TEXT NOT NULL DEFAULT 'Managed marketing package', ADD COLUMN "description" TEXT, ADD COLUMN "sortOrder" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "durationDays" INTEGER, ADD COLUMN "postCount" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "videoCount" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "storyCount" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "estimatedReachMetadata" JSONB, ADD COLUMN "createdByUserId" TEXT, ADD COLUMN "activatedByUserId" TEXT;
ALTER TABLE "ManagedMarketingPackageVersion" ADD CONSTRAINT "ManagedMarketingPackageVersion_non_negative" CHECK ("priceAmount" >= 0 AND "postCount" >= 0 AND "videoCount" >= 0 AND "storyCount" >= 0 AND ("durationDays" IS NULL OR "durationDays" >= 0));
CREATE TABLE "ManagedMarketingChannelDefinition" ("id" TEXT NOT NULL,"publicReference" TEXT NOT NULL,"code" TEXT NOT NULL,"displayName" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"sortOrder" INTEGER NOT NULL DEFAULT 0,"manualExecutionSupported" BOOLEAN NOT NULL DEFAULT true,"automatedProviderCapability" TEXT NOT NULL DEFAULT 'MANUAL_AVAILABLE',"providerConfigurationState" TEXT NOT NULL DEFAULT 'NOT_CONFIGURED',"metadata" JSONB,"createdByUserId" TEXT,"updatedByUserId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ManagedMarketingChannelDefinition_pkey" PRIMARY KEY("id"));
CREATE TABLE "ManagedMarketingPackageChannel" ("id" TEXT NOT NULL,"packageVersionId" TEXT NOT NULL,"channelDefinitionId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ManagedMarketingPackageChannel_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "ManagedMarketingChannelDefinition_publicReference_key" ON "ManagedMarketingChannelDefinition"("publicReference"); CREATE UNIQUE INDEX "ManagedMarketingChannelDefinition_code_key" ON "ManagedMarketingChannelDefinition"("code"); CREATE UNIQUE INDEX "ManagedMarketingPackageChannel_package_channel_key" ON "ManagedMarketingPackageChannel"("packageVersionId","channelDefinitionId");
ALTER TABLE "ManagedMarketingPackageChannel" ADD CONSTRAINT "ManagedMarketingPackageChannel_package_fkey" FOREIGN KEY("packageVersionId") REFERENCES "ManagedMarketingPackageVersion"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "ManagedMarketingPackageChannel" ADD CONSTRAINT "ManagedMarketingPackageChannel_channel_fkey" FOREIGN KEY("channelDefinitionId") REFERENCES "ManagedMarketingChannelDefinition"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
